using System;
using UnityEngine;
using UnityEngine.InputSystem;
namespace LWS.TruckBowling.Editor {
public static class BowlingFixtures {
 static int checks;static void Check(bool condition,string message){checks++;if(!condition)throw new Exception("BOWLING_FIXTURE_FAILED "+message);}
 static BowlingScore Game(params int[] rolls){var s=new BowlingScore();foreach(int p in rolls)s.Record(p);return s;}
 static BowlingScore NineOpen(){var s=new BowlingScore();for(int i=0;i<9;i++){s.Record(0);s.Record(0);}return s;}
 public static void Run(){checks=0;var gutters=new BowlingScore();for(int i=0;i<20;i++)gutters.Record(0);Check(gutters.Finished&&gutters.FinalTotal==0,"all gutters zero");var perfect=new BowlingScore();for(int i=0;i<12;i++)perfect.Record(10);Check(perfect.Finished&&perfect.FinalTotal==300,"twelve strikes 300");var spares=new BowlingScore();for(int i=0;i<21;i++)spares.Record(5);Check(spares.Finished&&spares.FinalTotal==150,"all five spares plus five 150");var nines=new BowlingScore();for(int i=0;i<10;i++){nines.Record(9);nines.Record(0);}Check(nines.FinalTotal==90,"all nine misses 90");
  var pending=Game(10);Check(pending.Cumulative(0)==null&&pending.ResolvedTotal==0,"strike unresolved until two rolls");pending.Record(10);Check(pending.Cumulative(0)==null,"double still pending");pending.Record(3);Check(pending.Cumulative(0)==23,"first strike resolves across frames");pending.Record(4);Check(pending.Cumulative(1)==40&&pending.Cumulative(2)==47,"mixed consecutive strike open cumulative");
  var mixed=Game(10,7,3,9,0,10,0,8,8,2,0,6,10,10,10,8,1);Check(mixed.Finished&&mixed.FinalTotal==167,"mixed standard game 167");
  var tenth=NineOpen();tenth.Record(10);Check(tenth.FreshRack&&tenth.RemainingPins==10&&!tenth.Finished,"tenth strike fresh rack bonus one");tenth.Record(6);Check(!tenth.FreshRack&&tenth.RemainingPins==4&&tenth.Ball==2,"partial second fill ball preserves four pins");tenth.Record(4);Check(tenth.FinalTotal==20&&tenth.Symbols(9)=="X 6 /","tenth X six spare twenty");
  tenth=NineOpen();tenth.Record(6);Check(!tenth.FreshRack&&tenth.RemainingPins==4,"tenth open preserves survivors");tenth.Record(4);Check(tenth.FreshRack&&tenth.RemainingPins==10&&tenth.Ball==2,"tenth spare fresh bonus rack");tenth.Record(10);Check(tenth.FinalTotal==20&&tenth.Symbols(9)=="6 / X","tenth spare bonus strike twenty");
  tenth=NineOpen();tenth.Record(10);tenth.Record(10);Check(tenth.FreshRack&&tenth.RemainingPins==10,"double tenth strike fresh third rack");tenth.Record(10);Check(tenth.FinalTotal==30,"tenth triple strike thirty");tenth=NineOpen();tenth.Record(9);tenth.Record(0);Check(tenth.Finished&&tenth.Deliveries==20,"tenth open ends with no bonus");bool rejected=false;try{tenth.Record(1);}catch(InvalidOperationException){rejected=true;}Check(rejected,"completed game rejects extra deliveries");
  var rack=Game(4);Check(!rack.FreshRack&&rack.RemainingPins==6,"ordinary first retains six");rejected=false;try{rack.Record(7);}catch(ArgumentOutOfRangeException){rejected=true;}Check(rejected&&rack.Deliveries==1,"cannot count more than survivors");rack.Record(6);Check(rack.FreshRack&&rack.Frame==1,"spare advances fresh");rack.Record(10);Check(rack.FreshRack&&rack.Frame==2,"ordinary strike advances fresh");Check(Game(0,0).Symbols(0)=="− −","miss display");
  var setup=new BowlingSetup{count=4};for(int i=0;i<4;i++)setup.players[i].source=BowlingSource.Keyboard;Check(setup.Validate(out _),"four nonoverlapping keyboard clusters");setup.players[1].forward=Key.W;Check(!setup.Validate(out _),"simultaneous keyboard duplicate rejected");setup.mode=BowlingMode.HotSeat;Check(setup.Validate(out _),"inactive hot-seat shared keyboard allowed");setup.players[1].forward=Key.Escape;Check(!setup.Validate(out _),"Escape rejected even hot seat");setup.players=BowlingSetup.Defaults();var pad=InputSystem.AddDevice<Gamepad>("Bowling ownership fixture");try{setup.mode=BowlingMode.Simultaneous;setup.players[0].source=BowlingSource.LeftStick;setup.players[1].source=BowlingSource.RightStick;setup.players[0].pad=setup.players[1].pad=pad;Check(setup.Validate(out _),"shared controller complementary stick ownership");setup.players[1].source=BowlingSource.LeftStick;Check(!setup.Validate(out _),"duplicate stick rejected");setup.players[1].source=BowlingSource.WholeController;Check(!setup.Validate(out _),"whole pad excludes sharing");setup.mode=BowlingMode.HotSeat;Check(setup.Validate(out _),"hot-seat shared pad allowed");}finally{InputSystem.RemoveDevice(pad);}Debug.Log("BOWLING_FIXTURES_PASS "+checks);
 }
}
}